import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"62、【小过】 艮下震上","description":"温公易说 - 62、【小过】 艮下震上","frontmatter":{"title":"62、【小过】 艮下震上","description":"温公易说 - 62、【小过】 艮下震上"},"headers":[],"relativePath":"zh/classics/wengong/063.md","filePath":"zh/classics/wengong/063.md"}'),n={name:"zh/classics/wengong/063.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_62、【小过】-艮下震上" tabindex="-1">62、【小过】 艮下震上 <a class="header-anchor" href="#_62、【小过】-艮下震上" aria-label="Permalink to “62、【小过】 艮下震上”">​</a></h1><p>注意</p><p>案原本缺。</p><h3 id="彖曰-小过-小者过而亨也。过以利贞-与时行也。柔得中-是以小事吉也。刚失位而不中-是以不可大事也。有飞鸟之象焉-飞鸟遗之音-不宜上-宜下-大吉。上逆而下顺也。" tabindex="-1">彖曰：小过，小者过而亨也。过以利贞，与时行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飞鸟之象焉，飞鸟遗之音，不宜上，宜下，大吉。上逆而下顺也。 <a class="header-anchor" href="#彖曰-小过-小者过而亨也。过以利贞-与时行也。柔得中-是以小事吉也。刚失位而不中-是以不可大事也。有飞鸟之象焉-飞鸟遗之音-不宜上-宜下-大吉。上逆而下顺也。" aria-label="Permalink to “彖曰：小过，小者过而亨也。过以利贞，与时行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飞鸟之象焉，飞鸟遗之音，不宜上，宜下，大吉。上逆而下顺也。”">​</a></h3><h3 id="象曰-山上有雷-小过。君子以行过乎恭-丧过乎哀-用过乎俭。" tabindex="-1">象曰：山上有雷，小过。君子以行过乎恭，丧过乎哀，用过乎俭。 <a class="header-anchor" href="#象曰-山上有雷-小过。君子以行过乎恭-丧过乎哀-用过乎俭。" aria-label="Permalink to “象曰：山上有雷，小过。君子以行过乎恭，丧过乎哀，用过乎俭。”">​</a></h3><h3 id="初六-飞鸟以凶-象曰-飞鸟以凶-不可如何也。" tabindex="-1">初六：飞鸟以凶 象曰：飞鸟以凶，不可如何也。 <a class="header-anchor" href="#初六-飞鸟以凶-象曰-飞鸟以凶-不可如何也。" aria-label="Permalink to “初六：飞鸟以凶 象曰：飞鸟以凶，不可如何也。”">​</a></h3><h3 id="六二-过其祖-遇其妣-不及其君-遇其臣-无咎-象曰-不及其君-臣不可过也。" tabindex="-1">六二：过其祖，遇其妣，不及其君，遇其臣，无咎 象曰：不及其君，臣不可过也。 <a class="header-anchor" href="#六二-过其祖-遇其妣-不及其君-遇其臣-无咎-象曰-不及其君-臣不可过也。" aria-label="Permalink to “六二：过其祖，遇其妣，不及其君，遇其臣，无咎 象曰：不及其君，臣不可过也。”">​</a></h3><h3 id="九三-弗过防之-从或戕之-凶-象曰-从或戕之-凶-如何也。" tabindex="-1">九三：弗过防之，从或戕之，凶 象曰：从或戕之，凶，如何也。 <a class="header-anchor" href="#九三-弗过防之-从或戕之-凶-象曰-从或戕之-凶-如何也。" aria-label="Permalink to “九三：弗过防之，从或戕之，凶 象曰：从或戕之，凶，如何也。”">​</a></h3><h3 id="九四-无咎-弗过遇之-往厉必戒-勿用永贞-象曰-弗过遇之-位不当也。往厉必戒-终不可长也。" tabindex="-1">九四：无咎，弗过遇之，往厉必戒，勿用永贞 象曰：弗过遇之，位不当也。往厉必戒，终不可长也。 <a class="header-anchor" href="#九四-无咎-弗过遇之-往厉必戒-勿用永贞-象曰-弗过遇之-位不当也。往厉必戒-终不可长也。" aria-label="Permalink to “九四：无咎，弗过遇之，往厉必戒，勿用永贞 象曰：弗过遇之，位不当也。往厉必戒，终不可长也。”">​</a></h3><h3 id="六五-密云不雨-自我西郊-公弋取彼在穴-象曰-密云不雨-已上也。" tabindex="-1">六五：密云不雨，自我西郊，公弋取彼在穴 象曰：密云不雨，已上也。 <a class="header-anchor" href="#六五-密云不雨-自我西郊-公弋取彼在穴-象曰-密云不雨-已上也。" aria-label="Permalink to “六五：密云不雨，自我西郊，公弋取彼在穴 象曰：密云不雨，已上也。”">​</a></h3><h3 id="上六-弗遇过之-飞鸟离之-凶-是谓灾眚-象曰-弗遇过之-已亢也。" tabindex="-1">上六：弗遇过之，飞鸟离之，凶，是谓灾眚 象曰：弗遇过之，已亢也。 <a class="header-anchor" href="#上六-弗遇过之-飞鸟离之-凶-是谓灾眚-象曰-弗遇过之-已亢也。" aria-label="Permalink to “上六：弗遇过之，飞鸟离之，凶，是谓灾眚 象曰：弗遇过之，已亢也。”">​</a></h3>',11)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
